export type V1474SeedEvidenceSource = {
  sourceKey: string
  title: string
  url: string
  accessedAt: string
}

export type V1474ProcessConstraintCondition = {
  field:
    | 'climate_signal'
    | 'weather_impact_band'
    | 'thermal_zone'
    | 'method_variant_code'
    | 'element_variant_code'
    | 'monthly_climate_signal'
    | 'project_type_code'
    | 'structure_type_code'
    | 'space_cleanliness_grade'
    | 'danger_control_level'
    | 'work_hour_policy'
    | 'environment_control_signal'
    | 'municipal_connection_status'
  operator: 'includes_any' | 'equals_any'
  values: string[]
}

export type V1474ProcessConstraintConditionalEffect = {
  id: string
  when: V1474ProcessConstraintCondition[]
  effect:
    | 'tighten_overlap_release'
    | 'require_project_fact_gate'
    | 'confidence_down'
    | 'candidate_only'
  minReleaseQuantityPercentDelta?: number
  partialOverlapRatioMultiplier?: number
  quantityEvidenceRequirement?:
    | 'not_applicable'
    | 'real_quantity_required_for_auto_release'
    | 'real_or_default_quantity_proxy_allowed'
    | 'scope_proxy_allowed_as_low_confidence'
  quantityProxyRiskLevel?: 'not_applicable' | 'low' | 'medium' | 'high'
  curationBasis: string
  businessReasonTemplate: string
  evidenceSourceKeys?: string[]
}

export type V1474ProcessConstraintRule = {
  stableCode: string
  keywords: string[]
  matchStrategy: 'structured_code_first_then_keyword_fallback'
  requiredKeywordGroups: string[][]
  excludedKeywordTerms: string[]
  standardCatalogCodePrefixes: string[]
  templateNodeStableCodePrefixes: string[]
  applicableCatalogGroups: string[]
  applicableDurationContributionModes: Array<
    | 'duration_bearing'
    | 'embedded_check'
    | 'quality_gate'
    | 'external_wait'
    | 'record_only'
    | 'handover_marker'
  >
  constraintType:
    | 'overlap_allowed'
    | 'technical_interval'
    | 'acceptance_wait'
    | 'curing_wait'
    | 'test_report_wait'
    | 'handover_wait'
    | 'commissioning_wait'
    | 'weather_window'
    | 'work_hour_window'
    | 'environment_control'
    | 'municipal_connection_wait'
    | 'safety_control_release'
    | 'monitoring_observation_wait'
    | 'temperature_control_window'
    | 'operation_permit_release'
    | 'confined_space_atmosphere_release'
    | 'temporary_power_isolation_release'
    | 'road_occupation_permit_release'
    | 'pollution_alert_release'
    | 'noise_sensitive_period_release'
  applicationMode: 'edge_lag' | 'edge_overlap' | 'gate_wait' | 'confidence_only'
  impactMode: 'duration_lookup' | 'overlap_ratio' | 'blocking_start' | 'confidence_only'
  runtimeActionPolicy: 'auto_apply_when_no_explicit_carrier' | 'candidate_only' | 'confidence_only'
  timeSourcePolicy:
    | 'standard_work_duration_seed_only'
    | 'explicit_carrier_or_standard_work_duration'
    | 'project_fact_then_standard_work_duration'
    | 'acceptance_timeline_then_standard_work_duration'
  durationLookupPolicy: 'route_to_standard_work_duration_seed'
  durationLookupKeys: string[]
  carrierProcessHints: string[]
  durationAuthorityPolicy: 'no_duration_values_in_process_constraint'
  partialOverlapRatio: number
  startAfterPercent: number
  scopeGranularity: 'task' | 'room' | 'zone' | 'floor' | 'building' | 'segment' | 'system'
  gateRequired: boolean
  releaseQuantityPolicy:
    | 'not_applicable'
    | 'real_task_quantity_then_standard_duration_quantity_proxy_then_scope_proxy'
  minReleaseQuantityPercent: number
  quantitySourcePriority: Array<
    | 'task_planned_completed_quantity'
    | 'standard_work_duration_default_quantity'
    | 'scope_granularity_proxy'
  >
  quantityEvidenceRequirement:
    | 'not_applicable'
    | 'real_quantity_required_for_auto_release'
    | 'real_or_default_quantity_proxy_allowed'
    | 'scope_proxy_allowed_as_low_confidence'
  quantityReleaseEvidenceChecklist: Array<
    | 'task_planned_completed_quantity'
    | 'accepted_workface_or_scope'
    | 'gate_acceptance_or_test_record'
    | 'standard_work_duration_default_quantity_proxy'
    | 'scope_granularity_proxy'
  >
  quantityProxyRiskLevel: 'not_applicable' | 'low' | 'medium' | 'high'
  insufficientQuantityPolicy: 'candidate_only_until_real_quantity_or_scope_release'
  quantityDoubleCountPolicy: 'standard_work_duration_owns_default_quantity_process_constraint_owns_release_threshold'
  relationshipScope: 'same_parent_edge' | 'cross_scope_edge' | 'same_parent_or_cross_scope_edge'
  relationInputPolicy: 'requires_existing_relation'
  dependencyCreationPolicy: 'never_create_dependency'
  parallelAllowedPolicy: 'parallel_allowed_is_no_edge_not_overlap'
  supportedRelationKinds: Array<'hard_sequence' | 'soft_sequence' | 'acceptance_gate' | 'dependency_intent' | 'explicit_task_dependency'>
  explicitCarrierPolicy: 'skip_duration_add_when_explicit_carrier_process_exists'
  durationDoubleCountPolicy: 'standard_work_duration_owns_all_day_values_process_constraint_owns_edge_routing'
  conditionalEffects: V1474ProcessConstraintConditionalEffect[]
  boundaryPolicyNotes: string[]
  backValidationPolicy: 'candidate_only_from_execution_history'
  businessReasonTemplate: string
  sourceStandard: 'national_standard' | 'industry_standard' | 'system_default' | 'enterprise_method'
  sourceVersion: string
  sourceClauseRef: string
  evidenceSourceKeys: string[]
  webVerified: true
  reviewNeeded: false
  confidence: 'high' | 'medium' | 'low'
  isActive?: boolean
}

type V1474ProcessConstraintRuleInput = Omit<
  V1474ProcessConstraintRule,
  | 'applicationMode'
  | 'impactMode'
  | 'runtimeActionPolicy'
  | 'timeSourcePolicy'
  | 'durationLookupPolicy'
  | 'durationLookupKeys'
  | 'carrierProcessHints'
  | 'durationAuthorityPolicy'
  | 'matchStrategy'
  | 'requiredKeywordGroups'
  | 'excludedKeywordTerms'
  | 'standardCatalogCodePrefixes'
  | 'templateNodeStableCodePrefixes'
  | 'applicableCatalogGroups'
  | 'applicableDurationContributionModes'
  | 'partialOverlapRatio'
  | 'startAfterPercent'
  | 'scopeGranularity'
  | 'gateRequired'
  | 'releaseQuantityPolicy'
  | 'minReleaseQuantityPercent'
  | 'quantitySourcePriority'
  | 'quantityEvidenceRequirement'
  | 'quantityReleaseEvidenceChecklist'
  | 'quantityProxyRiskLevel'
  | 'insufficientQuantityPolicy'
  | 'quantityDoubleCountPolicy'
  | 'relationshipScope'
  | 'relationInputPolicy'
  | 'dependencyCreationPolicy'
  | 'parallelAllowedPolicy'
  | 'supportedRelationKinds'
  | 'explicitCarrierPolicy'
  | 'durationDoubleCountPolicy'
  | 'conditionalEffects'
  | 'boundaryPolicyNotes'
  | 'backValidationPolicy'
  | 'businessReasonTemplate'
> & Partial<Pick<
  V1474ProcessConstraintRule,
  | 'applicationMode'
  | 'impactMode'
  | 'runtimeActionPolicy'
  | 'timeSourcePolicy'
  | 'durationLookupKeys'
  | 'carrierProcessHints'
  | 'requiredKeywordGroups'
  | 'excludedKeywordTerms'
  | 'standardCatalogCodePrefixes'
  | 'templateNodeStableCodePrefixes'
  | 'applicableCatalogGroups'
  | 'applicableDurationContributionModes'
  | 'partialOverlapRatio'
  | 'startAfterPercent'
  | 'scopeGranularity'
  | 'gateRequired'
  | 'releaseQuantityPolicy'
  | 'minReleaseQuantityPercent'
  | 'quantitySourcePriority'
  | 'quantityEvidenceRequirement'
  | 'quantityReleaseEvidenceChecklist'
  | 'quantityProxyRiskLevel'
  | 'relationshipScope'
  | 'supportedRelationKinds'
  | 'conditionalEffects'
  | 'boundaryPolicyNotes'
  | 'businessReasonTemplate'
>>

function inferApplicationMode(rule: V1474ProcessConstraintRuleInput): V1474ProcessConstraintRule['applicationMode'] {
  if (rule.applicationMode) return rule.applicationMode
  if (rule.constraintType === 'overlap_allowed') return 'edge_overlap'
  if ((rule.partialOverlapRatio ?? 0) > 0) return 'edge_overlap'
  if (rule.constraintType === 'acceptance_wait') return 'gate_wait'
  return 'edge_lag'
}

function inferStandardCatalogCodePrefixes(rule: V1474ProcessConstraintRuleInput): string[] {
  const text = `${rule.stableCode} ${rule.keywords.join(' ')} ${rule.sourceVersion}`.toLowerCase()
  const matches: string[] = []
  const add = (...prefixes: string[]) => matches.push(...prefixes)
  if (/earthwork|foundation|pile|basement|dewatering|excavation|cushion|backfill|桩|土方|基坑|垫层|回填/.test(text)) add('01', 'FND')
  if (/rebar|formwork|concrete|prefab|grouting|钢筋|模板|混凝土|装配|套筒/.test(text)) add('02', 'PRE')
  if (/masonry|plaster|painting|floor|door|window|bathroom|curtain|facade|砌体|抹灰|涂料|门窗|卫生间|地面|幕墙|外墙/.test(text)) add('03', '05', 'FAC')
  if (/roof|waterproof|insulation|屋面|防水|保温/.test(text)) add('04')
  if (/pipe|drainage|water_supply|fire_pipe|municipal|landscape|给水|排水|消防管|市政|景观/.test(text)) add('05', 'MUN')
  if (/mep|hvac|duct|cleanroom|medical_gas|空调|风管|洁净|医用气体|机电/.test(text)) add('06', 'MEP', 'CLN')
  if (/electrical|cable|conduit|distribution|grounding|电气|电缆|配管|配电|接地/.test(text)) add('07')
  if (/intelligent|structured|alarm|fire_alarm|fire_subsystem|linkage|commissioning|智能|综合布线|火灾报警|消防联动|联动调试/.test(text)) add('08', 'INT')
  if (/elevator|电梯/.test(text)) add('09')
  if (/steel|钢结构|楼承板/.test(text)) add('02-03', 'STL')
  return Array.from(new Set(matches))
}

function inferApplicableCatalogGroups(rule: V1474ProcessConstraintRuleInput): string[] {
  const text = `${rule.stableCode} ${rule.keywords.join(' ')} ${rule.sourceVersion}`.toLowerCase()
  if (/site|临设|现场/.test(text)) return ['site_management', 'core_quality', 'specialty']
  if (/danger|危大|支护|基坑|吊装/.test(text)) return ['danger_control', 'core_quality', 'specialty']
  if (/quality|acceptance|验收|检测|test|commissioning/.test(text)) return ['core_quality', 'quality_responsibility', 'specialty']
  if (/cleanroom|medical|steel|facade|curtain|municipal|landscape|intelligent|mep|specialty|洁净|医用|钢结构|幕墙|市政|景观|智能|消防/.test(text)) {
    return ['core_quality', 'specialty']
  }
  return ['core_quality', 'specialty']
}

function inferQuantityEvidenceRequirement(
  rule: V1474ProcessConstraintRuleInput,
  applicationMode: V1474ProcessConstraintRule['applicationMode'],
  gateRequired: boolean,
  minReleaseQuantityPercent: number,
): V1474ProcessConstraintRule['quantityEvidenceRequirement'] {
  if (rule.quantityEvidenceRequirement) return rule.quantityEvidenceRequirement
  if (applicationMode !== 'edge_overlap') return 'not_applicable'
  if (gateRequired || minReleaseQuantityPercent >= 85) return 'real_quantity_required_for_auto_release'
  if (minReleaseQuantityPercent >= 70) return 'real_or_default_quantity_proxy_allowed'
  return 'scope_proxy_allowed_as_low_confidence'
}

function buildQuantityReleaseEvidenceChecklist(
  requirement: V1474ProcessConstraintRule['quantityEvidenceRequirement'],
): V1474ProcessConstraintRule['quantityReleaseEvidenceChecklist'] {
  if (requirement === 'not_applicable') return []
  if (requirement === 'real_quantity_required_for_auto_release') {
    return ['task_planned_completed_quantity', 'accepted_workface_or_scope', 'gate_acceptance_or_test_record']
  }
  if (requirement === 'real_or_default_quantity_proxy_allowed') {
    return [
      'task_planned_completed_quantity',
      'standard_work_duration_default_quantity_proxy',
      'accepted_workface_or_scope',
    ]
  }
  return ['scope_granularity_proxy', 'accepted_workface_or_scope']
}

function inferQuantityProxyRiskLevel(
  requirement: V1474ProcessConstraintRule['quantityEvidenceRequirement'],
): V1474ProcessConstraintRule['quantityProxyRiskLevel'] {
  if (requirement === 'not_applicable') return 'not_applicable'
  if (requirement === 'real_or_default_quantity_proxy_allowed') return 'medium'
  return 'high'
}

function buildBusinessReasonTemplate(
  rule: V1474ProcessConstraintRuleInput,
  applicationMode: V1474ProcessConstraintRule['applicationMode'],
  minReleaseQuantityPercent: number,
) {
  if (rule.businessReasonTemplate) return rule.businessReasonTemplate
  if (applicationMode === 'edge_overlap') {
    return `该工序边可按${rule.scopeGranularity ?? '工作面'}穿插，但需满足约 ${minReleaseQuantityPercent}% 的释放工作面/工程量，并完成必要门禁后再进入后续工序。`
  }
  if (applicationMode === 'gate_wait') return '该工序边存在验收、检测或调试门禁；具体日期和等待时间以显式承载工序、验收时间轴或工期 seed 为准。'
  return '该工序边存在工艺约束；process_constraint 只记录来源路由和置信度，不保存具体等待天数。'
}

function withV1474ProcessConstraintDefaults(rule: V1474ProcessConstraintRuleInput): V1474ProcessConstraintRule {
  const applicationMode = inferApplicationMode(rule)
  const isOverlap = applicationMode === 'edge_overlap'
  const impactMode = rule.impactMode
    ?? (isOverlap
      ? 'overlap_ratio'
      : applicationMode === 'confidence_only'
        ? 'confidence_only'
        : 'duration_lookup')
  const partialOverlapRatio = Math.max(0, Math.min(0.9, Number(rule.partialOverlapRatio ?? 0) || 0))
  const startAfterPercent = Math.max(0, Math.min(100, Number(rule.startAfterPercent ?? Math.round((1 - partialOverlapRatio) * 100)) || 100))
  const gateRequired = rule.gateRequired ?? (
    rule.constraintType === 'acceptance_wait'
    || rule.constraintType === 'test_report_wait'
    || rule.constraintType === 'commissioning_wait'
    || rule.constraintType === 'weather_window'
    || rule.constraintType === 'work_hour_window'
    || rule.constraintType === 'environment_control'
    || rule.constraintType === 'municipal_connection_wait'
    || rule.constraintType === 'safety_control_release'
    || rule.constraintType === 'monitoring_observation_wait'
    || rule.constraintType === 'temperature_control_window'
    || rule.constraintType === 'operation_permit_release'
    || rule.constraintType === 'confined_space_atmosphere_release'
    || rule.constraintType === 'temporary_power_isolation_release'
  )
  const minReleaseQuantityPercent = Math.max(0, Math.min(100, Number(rule.minReleaseQuantityPercent ?? startAfterPercent) || 0))
  const quantityEvidenceRequirement = inferQuantityEvidenceRequirement(rule, applicationMode, gateRequired, minReleaseQuantityPercent)

  return {
    ...rule,
    matchStrategy: 'structured_code_first_then_keyword_fallback',
    requiredKeywordGroups: rule.requiredKeywordGroups ?? [],
    excludedKeywordTerms: rule.excludedKeywordTerms ?? [],
    standardCatalogCodePrefixes: rule.standardCatalogCodePrefixes ?? inferStandardCatalogCodePrefixes(rule),
    templateNodeStableCodePrefixes: rule.templateNodeStableCodePrefixes ?? inferStandardCatalogCodePrefixes(rule),
    applicableCatalogGroups: rule.applicableCatalogGroups ?? inferApplicableCatalogGroups(rule),
    applicableDurationContributionModes: rule.applicableDurationContributionModes ?? ['duration_bearing', 'quality_gate', 'handover_marker'],
    applicationMode,
    impactMode,
    runtimeActionPolicy: rule.runtimeActionPolicy ?? (applicationMode === 'edge_overlap' ? 'candidate_only' : 'confidence_only'),
    timeSourcePolicy: rule.timeSourcePolicy ?? 'explicit_carrier_or_standard_work_duration',
    durationLookupPolicy: 'route_to_standard_work_duration_seed',
    durationLookupKeys: rule.durationLookupKeys ?? [rule.stableCode],
    carrierProcessHints: rule.carrierProcessHints ?? rule.keywords,
    durationAuthorityPolicy: 'no_duration_values_in_process_constraint',
    partialOverlapRatio,
    startAfterPercent,
    scopeGranularity: rule.scopeGranularity ?? 'zone',
    gateRequired,
    releaseQuantityPolicy: rule.releaseQuantityPolicy ?? (isOverlap
      ? 'real_task_quantity_then_standard_duration_quantity_proxy_then_scope_proxy'
      : 'not_applicable'),
    minReleaseQuantityPercent,
    quantitySourcePriority: rule.quantitySourcePriority ?? (isOverlap
      ? ['task_planned_completed_quantity', 'standard_work_duration_default_quantity', 'scope_granularity_proxy']
      : []),
    quantityEvidenceRequirement,
    quantityReleaseEvidenceChecklist: rule.quantityReleaseEvidenceChecklist
      ?? buildQuantityReleaseEvidenceChecklist(quantityEvidenceRequirement),
    quantityProxyRiskLevel: rule.quantityProxyRiskLevel ?? inferQuantityProxyRiskLevel(quantityEvidenceRequirement),
    insufficientQuantityPolicy: 'candidate_only_until_real_quantity_or_scope_release',
    quantityDoubleCountPolicy: 'standard_work_duration_owns_default_quantity_process_constraint_owns_release_threshold',
    relationshipScope: rule.relationshipScope ?? 'same_parent_or_cross_scope_edge',
    relationInputPolicy: 'requires_existing_relation',
    dependencyCreationPolicy: 'never_create_dependency',
    parallelAllowedPolicy: 'parallel_allowed_is_no_edge_not_overlap',
    supportedRelationKinds: rule.supportedRelationKinds ?? [
      'hard_sequence',
      'soft_sequence',
      'acceptance_gate',
      'dependency_intent',
      'explicit_task_dependency',
    ],
    explicitCarrierPolicy: 'skip_duration_add_when_explicit_carrier_process_exists',
    durationDoubleCountPolicy: 'standard_work_duration_owns_all_day_values_process_constraint_owns_edge_routing',
    conditionalEffects: normalizeProcessConstraintConditionalEffects(
      rule.conditionalEffects ?? inferDefaultProcessConstraintConditionalEffects(rule),
    ),
    boundaryPolicyNotes: rule.boundaryPolicyNotes ?? [
      'process_constraint only owns overlap, gate, source routing, and confidence effects on a dependency edge',
      'process_constraint must not store duration, waiting, or lag day values',
      'standard_work_duration owns explicit node duration and reference duration',
      'standard_work_duration owns default quantity and productivity; process_constraint only owns release thresholds on an existing edge',
      'same_parent_internal_flow, cross_item_workflow, and dependency_intent_templates own relationship creation',
      'parallel_allowed means no timing edge exists; process_constraint does not convert it into edge_overlap',
    ],
    backValidationPolicy: 'candidate_only_from_execution_history',
    businessReasonTemplate: buildBusinessReasonTemplate(rule, applicationMode, minReleaseQuantityPercent),
  }
}

