function inferMepTestingCommissioningMethodVariantCodes(rule: V1474ProcessConstraintRuleInput) {
  const text = [
    rule.stableCode,
    ...rule.keywords,
    rule.sourceClauseRef,
  ].join(' ').toLowerCase()
  const variants = ['mep_testing_commissioning']
  if (/pipe|plu|fir|管|试压|冲洗|pressure|flush/.test(text)) {
    variants.push('pipe_pressure_flush_function_test')
  }
  if (/electrical|wiring|grounding|insulation|ele|电气|接线|绝缘|接地/.test(text)) {
    variants.push('electrical_insulation_grounding_loop_test')
  }
  if (/hvac|duct|single.machine|parameter|hva|cln|空调|风管|单机|参数/.test(text)) {
    variants.push('hvac_single_machine_or_parameter_commissioning')
  }
  if (/intelligent|network|int|智能|网络|软件|联动/.test(text)) {
    variants.push('intelligent_network_configuration_test')
  }
  if (/building.energy|energy|节能/.test(text)) {
    variants.push('building_energy_acceptance_test')
  }
  if (/rectification|整改|复验/.test(text)) {
    variants.push('rectification_closeout_retest')
  }
  if (/handover|signoff|移交|交接|签认/.test(text)) {
    variants.push('handover_signoff')
  }
  if (/commissioning|调试|试运行/.test(text)) {
    variants.push('system_commissioning')
  }
  return Array.from(new Set(variants))
}

function inferDefaultProcessConstraintConditionalEffects(
  rule: V1474ProcessConstraintRuleInput,
): V1474ProcessConstraintConditionalEffect[] {
  if (!L5_MEP_TESTING_COMMISSIONING_CONDITIONAL_RULE_CODES.has(rule.stableCode)) return []

  return [{
    id: `${rule.stableCode.replace(/_/g, '-')}-project-fact-gate`,
    when: [
      {
        field: 'project_type_code',
        operator: 'includes_any',
        values: [
          'commercial',
          'complex_building',
          'data_center',
          'factory',
          'hospital',
          'hotel',
          'public_building',
        ],
      },
      {
        field: 'method_variant_code',
        operator: 'includes_any',
        values: inferMepTestingCommissioningMethodVariantCodes(rule),
      },
    ],
    effect: 'require_project_fact_gate',
    quantityEvidenceRequirement: 'not_applicable',
    quantityProxyRiskLevel: 'not_applicable',
    curationBasis: 'High-frequency MEP testing, pressure-test, commissioning, report-review and rectification gates must be released by project facts and carrier processes; process_constraint keeps edge confidence and source routing only, with no lag-day ownership.',
    businessReasonTemplate: 'MEP testing and commissioning release must confirm project type, system method, test records and rectification facts before trusting the existing edge.',
    evidenceSourceKeys: rule.evidenceSourceKeys,
  }]
}

