export const V1474_PROCESS_CONSTRAINT_SEED: V1474ProcessConstraintRule[] = (
  V1474_PROCESS_CONSTRAINT_SEED_INPUTS.map(withV1474ProcessConstraintDefaults)
)

export function findV1474ProcessConstraint(text: string) {
  const normalized = text.toLowerCase()
  return V1474_PROCESS_CONSTRAINT_SEED.find((item) => (
    item.keywords.some((keyword) => normalized.includes(keyword.toLowerCase()))
  )) ?? null
}

